        assert_eq!(ABI_X86_64.bind_nr, 49);
        assert_eq!(ABI_X86_64.recvmsg_nr, 47);
        assert_eq!(ABI_X86_64.sendto_nr, 44);
        assert_eq!(ABI_X86_64.close_nr, 3);
        assert_eq!(ABI_X86_64.fcntl_nr, 72);
